using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using HelpDeskPro.Api.Data; using HelpDeskPro.Api.Models; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens;
namespace HelpDeskPro.Api.Services;
public class AuthService { private readonly AppDbContext db; private readonly IConfiguration cfg; private readonly PasswordHasher<User> hasher=new(); public AuthService(AppDbContext db,IConfiguration cfg){this.db=db;this.cfg=cfg;} public async Task<object?> Login(string email,string password){ var u=await db.Users.Include(x=>x.Department).FirstOrDefaultAsync(x=>x.Email==email&&x.IsActive); if(u==null||hasher.VerifyHashedPassword(u,u.PasswordHash,password)==PasswordVerificationResult.Failed)return null; db.ActivityLogs.Add(new ActivityLog{Action="Logged in",Entity="User",EntityId=u.Id,UserId=u.Id}); await db.SaveChangesAsync(); var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.FullName),new Claim(ClaimTypes.Email,u.Email),new Claim(ClaimTypes.Role,u.Role.ToString())}; var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(cfg["Jwt:Key"]!)); var token=new JwtSecurityToken(cfg["Jwt:Issuer"],cfg["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddHours(8),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256)); return new {token=new JwtSecurityTokenHandler().WriteToken(token),user=new {u.Id,u.FullName,u.Email,Role=u.Role.ToString(),Department=u.Department?.Name}}; } }
